EXPORT ZZT_MATROWS()
BEGIN
  LOCAL D,W,R,Z;
  LOCAL P,Q,realResult,colResult,signedResult;
  HComplex:=1;
  D:=[[1,4],[3,8]];
  W:=[[1,1],[1,1],[1,1]];
  A:=0;
  IFERR R:=stddev(D,W); THEN R:="caught"; A:=A+10; END;
  Z:=stddev(W,D);
  P:=stddev([[ 1.00, .5 ],[3E0,8]],W);
  Q:=stddev(W,ZZT_MATRIX());
  L1:={R,Z,P,Q};
  W:=[[1,1],[1,1]];
  realResult:=stddev(D,W);
  W:=[[1],[1]];
  colResult:=stddev(D,W);
  W:=[[-1,1],[3,1]];
  signedResult:=stddev(D,W);
  RETURN {{TYPE(R),R,INSTRING(R,CHAR(10))},{TYPE(Z),Z},
          {TYPE(P),P},{TYPE(Q),Q},A,
          {TYPE(realResult),SIZE(realResult),realResult(1),realResult(2)},
          {TYPE(colResult),SIZE(colResult),colResult(1)},
          {TYPE(signedResult),TYPE(signedResult(1)),ROUND(IM(signedResult(1)),8)}};
END;
ZZT_MATRIX()
BEGIN
  A:=A+1;
  RETURN [[1,4],[3,8]];
END;

EXPORT ZZT_MATROWS()
BEGIN
  LOCAL R:=L1(1),Z:=L1(2),P:=L1(3),Q:=L1(4);
  RETURN {{TYPE(R),R,INSTRING(R,CHAR(10))},{TYPE(Z),Z},{TYPE(P),P},{TYPE(Q),Q}};
END;

EXPORT ZZT_MATROWS() BEGIN
LOCAL D,W,R,O:={}; HComplex:=1;
D:=[[1,4],[3,8]]; W:=[[1,1],[1,1],[1,1]]; IFERR R:=stddev(D,W); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
D:=[[1,4],[3,8],[9,18]]; W:=[[1,1],[1,1]]; IFERR R:=stddev(D,W); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
D:=[[1,4],[3,8]]; W:=[[-1,1],[3,1],[1,1]]; IFERR R:=stddev(D,W); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
D:=[[1,4],[3,8],[9,18]]; W:=[[-1,1],[3,1]]; IFERR R:=stddev(D,W); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
D:=[[1,4,9],[3,8,18]]; W:=[[1,1]]; IFERR R:=stddev(D,W); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
D:=[[1,4]]; W:=[[-1,1,2],[3,1,2]]; IFERR R:=stddev(D,W); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
D:=[[1.5,4],[3,8]]; W:=[[1.5,1],[1,1],[1,1]]; IFERR R:=stddev(D,W); O:=CONCAT(O,{{TYPE(R),R}}); THEN O:=CONCAT(O,{"caught"}); END;
RETURN O; END;

EXPORT ZZT_MATROWS() BEGIN
LOCAL D:=[[1,4],[3,8]], W:=[[1,1],[1,1],[1,1]], R,O:={}; HComplex:=1; M1:=D; M2:=W;
A:=0; R:=stddev(ZZT_MATRIX(),W); RETURN {A,TYPE(R),R}; END;
ZZT_MATRIX() BEGIN A:=A+1; RETURN [[1,4],[3,8]]; END;

EXPORT ZZT_MATROWS() BEGIN
LOCAL D:=[[1,4],[3,8]], W:=[[1,1],[1,1],[1,1]], R,O:={}; HComplex:=1; M1:=D; M2:=W;
A:=0; R:=stddev(W,ZZT_MATRIX()); RETURN {A,TYPE(R),R}; END;
ZZT_MATRIX() BEGIN A:=A+1; RETURN [[1,4],[3,8]]; END;
